type BlogPostPageProps = {
	postDetails: BlogPost;
	postContent: string;
};

export const getStaticProps: GetStaticProps<BlogPostPageProps, { slug: string }> = async ({
	params,
}) => {
	const DEFAULLANG = "en";
	const slug = params?.slug || "";
	if (!slug) throw new Error(`Invalid slug: "${slug}"`);

	const post = await loadData<RawBlogPostResponse>({ localPath: `blog/posts/${slug}.json` });
	const mdxCompiled = await compile({ content: post.content });

	return {
		props: {
			postDetails: {
				...post.details,
				content: post.details.content[DEFAULLANG],
			},
			postContent: mdxCompiled.code,
		},
	};
};

