import cn from "classnames";
import * as React from "react";
import { highlight } from "sugar-high";

import type UtilsTypes from "@diegofrayo-pkg/types";
import { createArray } from "@diegofrayo-pkg/utilities/arrays-and-objects";
import { throwError } from "@diegofrayo-pkg/utilities/misc";
import { generateSlug } from "@diegofrayo-pkg/utilities/strings";
import * as v from "@diegofrayo-pkg/validator";

import { Box, Button, Icon, Link, Pre } from "~/components/primitive";
import AnalyticsService from "~/modules/analytics";

import CopyToClipboardPopover from "./CopyToClipboardPopover";

export type SourceCodeProps = {
	code: UtilsTypes.React.Children;
	sourceURL?: string;
	className?: string;
};

function SourceCode({ code, sourceURL = "", className = "" }: SourceCodeProps) {
	// --- STATES & REFS ---
	const [highlightedCode, setHighlightedCode] = React.useState("");
	const [containerHeight, setContainerHeight] = React.useState<number | "auto">("auto");
	const containerRef = React.useRef<null | HTMLDivElement>(null);

	// --- UTILS ---
	const extractChildren = React.useCallback(function extractChildren(
		codeParam: SourceCodeProps["code"],
	) {
		const result = React.isValidElement(codeParam) ? codeParam.props.children : codeParam;

		return v.isString(result) ? result : throwError("Invalid text to copy or highlight");
	}, []);

	// --- EFFECTS ---
	React.useEffect(
		function highlightCode() {
			setHighlightedCode(highlight(extractChildren(code)));
		},
		[code, extractChildren],
	);

	React.useEffect(
		function onHighlightedCode() {
			if (highlightedCode && containerRef.current) {
				const sourceCodeHeight = containerRef.current.querySelector("pre")?.offsetHeight || 500;
				setContainerHeight(sourceCodeHeight > 500 ? 500 : "auto");
			}
		},
		[highlightedCode],
	);

	return (
		<Box
			className={cn(
				"dr-source-code",
				"relative overflow-hidden rounded-md border dr-bg-color-surface-200 dr-border-color-surface-300",
				className,
			)}
			style={{ height: containerHeight }}
			ref={containerRef}
			data-markdown-block
		>
			<Box className="absolute right-0 top-0 flex w-full justify-between pb-1 text-right dr-bg-color-surface-300">
				<Box className="ml-2 flex pt-2">
					{createArray(3).map((element) => {
						return (
							<Box
								key={generateSlug(`SourceCode-Box-element-${element}`)}
								className={cn("mr-1.5 inline-block rounded-full size-3 last:mr-0", {
									"bg-red-500": element === 1,
									"bg-yellow-500": element === 2,
									"bg-green-500": element === 3,
								})}
							/>
						);
					})}
				</Box>
				<Box>
					{v.isNotEmptyString(sourceURL) ? (
						<Link
							variant={Link.variant.SIMPLE}
							href={sourceURL}
							className="mr-2 inline-block"
							onClick={AnalyticsService.trackClickEvent("SOURCE_CODE|OPEN_LINK")}
							isExternalLink
						>
							<Icon icon={Icon.icon.EXTERNAL_LINK} />
						</Link>
					) : null}
					<CopyToClipboardPopover textToCopy={extractChildren(code)}>
						<Button
							variant={Button.variant.SIMPLE}
							className="mr-2 inline-block"
							onClick={AnalyticsService.trackClickEvent("SOURCE_CODE|COPY_CODE")}
						>
							<Icon icon={Icon.icon.COPY} />
						</Button>
					</CopyToClipboardPopover>
				</Box>
			</Box>
			<Pre
				variant={Pre.variant.UNSTYLED}
				className="max-h-full overflow-auto p-3 pt-10 text-base"
				dangerouslySetInnerHTML={{ __html: highlightedCode }}
			/>
		</Box>
	);
}

export default SourceCode;

