import cn from "classnames";
import { getMDXComponent, getMDXExport } from "mdx-bundler/client";
import * as React from "react";

import type UtilsTypes from "@diegofrayo-pkg/types";
import * as v from "@diegofrayo-pkg/validator";

import {
	Blockquote,
	Box,
	Code,
	Image,
	Link,
	List,
	Space,
	Text,
	Title,
} from "~/components/primitive";
import type { TitleProps } from "~/components/primitive/Title";
import { SourceCode } from "~/components/shared";

import styles from "./styles.module.css";

type MDXContentProps = {
	code: string;
	components?: UtilsTypes.Object;
	globals?: UtilsTypes.Object;
};

export function MDXContent({ code, components = {}, globals = {} }: MDXContentProps) {
	const Component = React.useMemo(() => getMDXComponent(code, globals), [code, globals]);

	return (
		<Box className={cn("dr-mdx-content", styles["dr-mdx-content"])}>
			<Component components={{ ...MDXComponents, ...components }} />
		</Box>
	);
}

export { getMDXExport };

// DOCS: https://mdxjs.com/table-of-components/
/* WARN:
 * I don't know how to type this object, so, I used any for this
 * It is not important to solve this
 */
// @ts-ignore
export const MDXComponents = {
	// --- PRIMITIVE COMPONENTS ---
	a: function CustomA({ children, href }: UtilsTypes.DOM.HTMLElementAttributes["a"]) {
		return (
			<Link
				href={href || ""}
				variant={Link.variant.STYLED}
				isExternalLink
			>
				{children}
			</Link>
		);
	},
	blockquote: Blockquote,
	code: function CustomCode({ children }: UtilsTypes.DOM.HTMLElementAttributes["code"]) {
		if (v.isString(children)) {
			return <Code variant={Code.variant.STYLED}>{children}</Code>;
		}

		throw new Error("Code component: Invalid children");
	},
	h1: createTitleComponent("h1", {}),
	h2: createTitleComponent("h2", {}),
	h3: createTitleComponent("h3", {}),
	h4: createTitleComponent("h4", {}),
	hr: function CustomHr() {
		return <Space variant={Space.variant.DASHED} />;
	},
	img: function CustomImage(props: UtilsTypes.DOM.HTMLElementAttributes["img"]) {
		return (
			<Image
				{...props}
				alt={props.alt || ""}
				useNativeImage
			/>
		);
	},
	li: List.Item,
	p: Text,
	pre: function CustomPre({ children }: UtilsTypes.DOM.HTMLElementAttributes["pre"]) {
		return <SourceCode code={children} />;
	},
	ul: function CustomUl({ children }: UtilsTypes.DOM.HTMLElementAttributes["ul"]) {
		return <List variant={List.variant.SIMPLE}>{children}</List>;
	},

	// --- CUSTOM COMPONENTS ---
	Box,
	SourceCode,
};

// --- INTERNALS ---

function createTitleComponent(Tag: "h1" | "h2" | "h3" | "h4", props: Omit<TitleProps, "is">) {
	return function CustomTitle({ children }: UtilsTypes.DOM.HTMLElementAttributes["h1"]) {
		return (
			<Title
				{...props}
				is={Tag}
				variant={Title.variant.STYLED}
			>
				{children}
			</Title>
		);
	};
}

